    total_tier_1_capital = vars["v1"] + vars["v2"]
    return {
        "value": total_tier_1_capital,
        "trace": {
            "total_tier_1_capital": total_tier_1_capital,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
